// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address otherUser = address(0x1234);

    function setUp() public { 
        c = new C(); 
        vm.deal(otherUser, 1 ether);
    }

    function testFuzz_property() public {
        // Set initial blacklist state for otherUser
        vm.prank(otherUser);
        // We need to have some tokens to distribute first, so call getTokens from otherUser
        // But before that, ensure otherUser is not blacklisted

        // First, record blacklist value before call
        bool initialBlacklist = c.blacklist(otherUser);

        // Call NETM() which onlyOwner can call, but we don't have owner prank here
        // We need to interact through the public surface properly
        vm.prank(address(0xdead)); // Random address that is owner? No, owner is msg.sender of constructor
        // Actually owner is the contract deployer (this contract) so we can call NETM
        c.NETM();

        // Check that otherUser's blacklist status is unchanged
        bool finalBlacklist = c.blacklist(otherUser);
        assertTrue(initialBlacklist == finalBlacklist, "Blacklist changed for unrelated address");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 valueInput) public {
        vm.assume(caller != address(0));
        vm.assume(valueInput <= type(uint256).max / 100000); // avoid overflow in multiplication

        // Set up: ensure distribution is not finished and caller is not blacklisted
        vm.prank(caller);
        // We need to call NETM() which sets owner and gives them tokens
        // But we also need to ensure caller can call getTokens
        // First, call NETM() as owner to set up
        vm.prank(c.address); // Not possible, so we need to get owner
        // Actually, let's just call NETM() directly from the test (owner not set yet)
        c.NETM(); // This sets owner = msg.sender (the test contract)

        // Now simulate a call to getTokens() with a specific value
        // We need to prank a non-blacklisted address
        vm.prank(caller);
        // deal some ether to the caller to make payable work
        vm.deal(caller, 1 ether);

        // Record the caller's blacklist status before the call
        bool wasBlacklisted = c.blacklist(caller);
        vm.assume(!wasBlacklisted); // onlyWhitelist modifier

        // Call getTokens()
        (bool success, ) = address(c).call{value: valueInput}(abi.encodeWithSignature("getTokens()"));

        // Check the rule: after getTokens, the caller should be blacklisted if and only if value > 0 and totalRemaining > 0
        // The value parameter determines distribution amount
        // In the reference implementation, if toGive > 0, caller gets blacklisted
        // The actual value used is min(valueInput, totalRemaining) after state changes
        // But we can just check: if valueInput > 0 and totalRemaining before call > 0, then blacklist[caller] should be true

        // Get totalRemaining before call
        uint256 totalRemaining = c.totalRemaining();

        if (success && valueInput > 0 && valueInput <= totalRemaining) {
            // Then the reference would set blacklist[caller] = true
            assertTrue(c.blacklist(caller), "Caller should be blacklisted after getting tokens");
        } else {
            // Otherwise blacklist status should remain unchanged (false)
            assertTrue(!c.blacklist(caller), "Caller should not be blacklisted");
        }
    }
}

