pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, uint256 val) public {
        vm.assume(caller != address(0) && other != address(0) && other != caller);
        vm.assume(c.blacklist(caller) == false);
        vm.assume(c.blacklist(other) == false);

        // Set up value so that caller gets non-zero tokens
        vm.prank(caller);
        vm.assume(val > 0 && val <= c.totalRemaining());

        // Record blacklist before
        bool beforeCaller = c.blacklist(caller);
        bool beforeOther = c.blacklist(other);

        // Call NETM()
        vm.prank(caller);
        c.NETM();

        // Record blacklist after
        bool afterCaller = c.blacklist(caller);
        bool afterOther = c.blacklist(other);

        // Assert: caller's blacklist changed to true, other's unchanged
        assertTrue(afterCaller == !beforeCaller);
        assertTrue(afterOther == beforeOther);
    }
}

