pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other) public {
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);

        // Call NETM() to set initial state
        vm.prank(address(0xdead));
        c.NETM();

        // Ensure value is sufficient (it's set to 2500e18)
        // Give ETH so the contract can pay (value is large but we just need the call to proceed)
        vm.deal(caller, 1 ether);

        // Before calling getTokens, record blacklist status of other (should be false)
        bool otherBlacklistBefore = c.blacklist(other);

        // Call getTokens from caller
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}("");

        if (success && c.balanceOf(caller) > 0) {
            // If caller received tokens, they should be blacklisted in reference
            assertTrue(c.blacklist(caller) == true, "Caller should be blacklisted after receiving tokens");
            // Other address blacklist should remain unchanged
            assertTrue(c.blacklist(other) == otherBlacklistBefore, "Other address blacklist should remain unchanged");
        }
    }
}

