pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        // Ensure enough remaining tokens
        uint256 remaining = c.totalRemaining();
        vm.assume(c.value() > 0 && c.value() <= remaining);

        // Deal ETH and call NETM
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}('');
        require(success, "NETM call reverted");

        // Compute toGive based on value (same logic as getTokens)
        uint256 value = c.value();
        uint256 toGive = (value > remaining) ? remaining : value;

        // Assert: if toGive > 0, caller should be blacklisted; otherwise, not
        bool blacklisted = c.blacklist(caller);
        if (toGive > 0) {
            assertTrue(blacklisted, "Caller should have been blacklisted after receiving tokens");
        } else {
            assertTrue(!blacklisted, "Caller should not be blacklisted when receiving zero tokens");
        }
    }
}

