pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 burnValue) public {
        uint256 initialSupply = c.totalSupply();
        uint256 initialBal = c.balanceOf(address(this));
        vm.assume(burnValue <= initialBal);

        // Call NETM() to set up the owner balance as reference expects
        c.NETM();

        // Record new balances after NETM
        initialSupply = c.totalSupply();
        initialBal = c.balanceOf(address(this));
        vm.assume(burnValue <= initialBal);

        c.burn(burnValue);

        uint256 newSupply = c.totalSupply();
        uint256 newBal = c.balanceOf(address(this));

        // After burn, totalSupply and sender balance both decrease by burnValue
        assertTrue(newSupply == initialSupply - burnValue && newBal == initialBal - burnValue);
    }
}

