pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Record totalDistributed before any operation
        uint256 before = c.totalDistributed();

        // Call NETM() which is the only public entry point that modifies totalDistributed
        c.NETM();

        // The rule: totalDistributed must not decrease
        uint256 after = c.totalDistributed();
        assertTrue(after >= before);
    }

    // Additional fuzzing to test with varying initial state
