        uint256 sumBalancesBefore = c.balanceOf(user2) + c.balanceOf(user3);

        // Call NETM()
        c.NETM();

        // After NETM(), totalDistributed should equal balances[owner] + totalRemaining + all other balances
        // But note: owner gets totalDistributed, and totalRemaining should be unchanged
        uint256 totalDistributedAfter = c.totalDistributed();
        uint256 totalRemainingAfter = c.totalRemaining();
        uint256 ownerBalance = c.balanceOf(caller);
        uint256 sumOtherBalances = c.balanceOf(user2) + c.balanceOf(user3);

        // The invariant: ownerBalance + sumOtherBalances + totalRemainingAfter == totalDistributedAfter
