pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user1, address user2, address user3, uint256 callOrder) public {
        // Bound inputs to avoid trivial reverts
        vm.assume(user1 != address(0) && user2 != address(0) && user3 != address(0));
        vm.assume(user1 != user2 && user1 != user3 && user2 != user3);
        callOrder = bound(callOrder, 0, 2);

        // Perform sequence of NETM calls from different addresses
        address[3] memory users = [user1, user2, user3];
        for (uint256 i = 0; i < 3; i++) {
            vm.prank(users[i]);
            try c.NETM() {} catch {}
        }

        // Get state after all calls
        uint256 totalDistributed = c.totalDistributed();
        uint256 totalRemaining = c.totalRemaining();

        // Compute sum of all balances (we can only read balances of addresses that exist)
        // For simplicity, we check that totalDistributed + totalRemaining >= sum of known balances
        uint256 sumBalances = c.balanceOf(user1) + c.balanceOf(user2) + c.balanceOf(user3);

        // The invariant: totalDistributed + totalRemaining >= sumBalances (since there may be other holders)
        // But more precisely, totalDistributed = sumBalances + someOwnerBalance? Actually we can't read owner's balance via public getter.
        // Instead we check that totalDistributed is never less than totalRemaining + sumBalances (i.e., no negative balances)
        assertTrue(totalDistributed >= sumBalances + totalRemaining, "totalDistributed too small");
    }
}

