pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 initialSupply = 500000000e18;
    uint256 initialDistributed = 250000000e18;

    function setUp() public { c = new C(); }

    function testFuzz_property() public {
        // Record state before NETM call
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 totalDistributedBefore = c.totalDistributed();
        uint256 totalRemainingBefore = c.totalRemaining();

        // Call NETM which sets owner's balance to totalDistributed and should distribute
        c.NETM();

        // After NETM, owner gets totalDistributed tokens (the initial totalDistributed value)
        uint256 ownerBalance = c.balanceOf(c.owner());
        uint256 totalDistributedAfter = c.totalDistributed();
        uint256 totalRemainingAfter = c.totalRemaining();
        uint256 totalSupplyAfter = c.totalSupply();

        // General rule: totalRemaining after = totalSupply - totalDistributed - ownerBalance
        // Because NETM essentially gives owner the totalDistributed tokens from the remaining supply
        // totalRemaining = (totalSupply) - (totalDistributed + ownerBalance) = totalSupply - totalDistributed - ownerBalance
        uint256 expectedRemaining = totalSupplyAfter - totalDistributedAfter - ownerBalance;
        assertTrue(totalRemainingAfter == expectedRemaining, "totalRemaining invariant broken");
    }
}

