pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialValue, uint256 callCount) public {
        // Constrain initial value to be reasonable (not zero to see the decay)
        vm.assume(initialValue > 0 && initialValue <= 2500e18);
        vm.assume(callCount > 0 && callCount < 10); // Keep it bounded

        // Set initial value by manipulating state via NETM()? Actually we can't set value directly.
        // Use deal to give the contract ETH so that getTokens can run...
        // Actually we can call NETM() which sets balances[owner] = totalDistributed, but not value.
        // We need a way to change value. The only public way is getTokens which reduces value.
        // So we can call getTokens() repeatedly and check value after each call.

        // First, call NETM() to initialize owner
        c.NETM();

        // Get initial value before any getTokens calls
        uint256 prevValue = c.value();

        // Perform a sequence of getTokens calls (some may revert if blacklisted)
        for (uint256 i = 0; i < callCount; i++) {
            // Skip if totalRemaining is zero (can't distribute)
            (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("getTokens()"));
            if (success) {
                uint256 newValue = c.value();
                // The rule: value should either be unchanged (if call failed to distribute) or decreased by factor ~99999/100000
                // or become 0 if totalRemaining was exceeded. In the buggy version it becomes 0 always.
                // In the reference, if toGive > 0, value = (value / 100000) * 99999, which is <= value * 99999/100000.
                // If toGive == 0 (blacklisted), value stays same.
                // Also if value > totalRemaining, it gets capped, etc.
                // For the test, we check that if the call succeeded, value either stayed same (no distribution) or decreased.
                // But the reference should have value non-zero after first call if initial value > 0.
                // The bug sets value = 0 always.
                assertTrue(newValue <= prevValue, "Value should not increase");
                prevValue = newValue;
            }
        }

        // After all calls, check that value is not zero in the reference case (unless totalRemaining forced it)
        // Actually if many calls, eventually totalRemaining becomes 0 and distributionFinished, then getTokens reverts.
        // But value might become very small. The key invariant: value should never become 0 unless totalRemaining == 0.
        // The bug makes it 0 instantly after first getTokens call.
        // 
        // Better rule: after first successful getTokens, value should be strictly less than initialValue but greater than 0
        // unless totalRemaining was already 0. Let's check totalRemaining.

        if (c.totalRemaining() == 0) {
            assertTrue(c.value() == 0);
        } else {
            // After at least one successful getTokens, the reference keeps value > 0
            (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("getTokens()"));
            if (success) {
                assertTrue(c.value() > 0, "Value should be positive after one call if totalRemaining > 0");
            }
        }
    }
}

