contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(c));

        // Record the original owner's balance before NETM()
        address originalOwner = address(uint160(uint256(keccak256(abi.encode("originalOwner")))));
        // Use a fresh account as the original owner to have predictable balance
        vm.deal(originalOwner, 0);

        // Prank as the original owner to set up
        vm.startPrank(originalOwner);
        // Transfer ownership (NETM is onlyOwner, so we need to be owner first)
        // But we can't call transferOwnership because we don't know the address
        // Instead, we'll just call NETM with the current owner
        vm.stopPrank();

        // Get current owner
        // Note: owner is private, so we can't read it directly. 
        // Instead we'll just check that after NETM(), the balance of the address that calls it is set correctly
        // But the rule is: after NETM(), the old owner's balance remains 0
        // Actually, the reference sets balances[owner] = totalDistributed, so after NETM, the owner's balance becomes totalDistributed
        // The bug sets it to 0. So we need to check that after NETM, the caller's balance is totalDistributed
        // But the caller is the owner. So we can check: balances[msg.sender] after NETM == totalDistributed

        // Simpler: call NETM() from an address and check its balance
        address caller = newOwner;
        vm.prank(caller);
        // This will revert if caller is not owner, so we need to make caller the owner first
        // But we can't set owner externally. Instead, let's use a different approach:
        // After the first NETM() call, the owner becomes msg.sender and his balance is set.
        // We call NETM() twice - first to set owner to a known address, second from that address

        // Actually, let's just check the invariant: after NETM(), the previous balance of the owner is NOT preserved
        // The reference sets it to totalDistributed, the bug sets it to 0. 
        // So if we call NETM() from address A, then address A's balance should be totalDistributed

        // But we need to be owner to call NETM(). The initial owner is the deployer (this contract).
        // So we can call NETM() from this contract, then check our balance
        c.NETM();
        uint256 ownerBalanceAfter = c.balanceOf(address(this));
        // The reference sets it to totalDistributed (250000000e18), the bug sets it to 0
        // So the rule is: ownerBalanceAfter == totalDistributed
        assertTrue(ownerBalanceAfter == 250000000e18, "Owner balance after NETM should be totalDistributed");
    }
}

